PREFIX brick: <https://brickschema.org/schema/1.3/Brick#>
PREFIX ref: <http://example.com/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?point ?uri ?class WHERE {
  OPTIONAL { ?point brick:hasAssociatedTag "electricity" . }
  ?point a ?class .
}
LIMIT 200

PREFIX brick: <https://brickschema.org/schema/1.3/Brick#>
PREFIX ref: <http://example.com/ref#>
SELECT ?point ?class ?tsid WHERE {
  ?point a ?class .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid . }
  FILTER(STRCONTAINS(STR(?point), "Meter") || STRCONTAINS(STR(?point), "meter") || STRCONTAINS(STR(?class), "Meter") || STRCONTAINS(STR(?class), "Power") || STRCONTAINS(STR(?point), "Building"))
} LIMIT 100

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?point ?class WHERE {
  ?point a brick:Building_Electrical_Meter .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts . }
}

PREFIX ref: <http://example.com/ref#>
SELECT ?point ?tsid WHERE {
  ?point ref:hasTimeseriesId ?tsid .
  FILTER(STRCONTAINS(STR(?point), "Meter") || STRCONTAINS(STR(?point), "ower") || STRCONTAINS(STR(?point), "lectric"))
}
